   let settled=false;
   const settle=async success=>{if(settled)return;settled=true;try{if(success)await commitCreditReservation(session.user.id,reference,{reason,requestId:req.requestId});else await releaseCreditReservation(session.user.id,reference)}catch(e){console.error('[Pothub toolbar credit settlement]',redactSecrets(e.message))}};
