const AUTH_CODES={github_not_configured:'GitHub login is not configured on the server. Add GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET in Vercel, then redeploy.',session_secret_missing:'SESSION_SECRET is missing or shorter than 32 characters in Vercel. Set a random value of 32+ characters, then redeploy.',state_cookie_missing:'The browser did not send back the GitHub sign-in cookie. Start Developer sign-in again in the same browser. If it repeats, the app and API are on different domains or cookies are blocked.',state_mismatch:'The GitHub sign-in response did not match this browser session. Start Developer sign-in again from the app.',github_denied:'GitHub authorization was cancelled or access was denied.',github_redirect_mismatch:'GitHub rejected the redirect URL. In the GitHub OAuth app, the callback must be exactly APP_URL + /api/auth/github/callback.',github_code_invalid:'The GitHub authorization code expired or was already used. Start sign-in again.',github_token_failed:'GitHub did not issue an access token. Check GITHUB_CLIENT_ID and GITHUB_CLIENT_SECRET match the same OAuth app.',github_profile_failed:'GitHub did not return your profile. Retry; if it repeats, check the OAuth app and granted scopes.',database_unavailable:'Pothub account storage is unavailable. Check FIREBASE_SERVICE_ACCOUNT_JSON and that Firestore is enabled (open /api/health for details).',github_unreachable:'The server could not reach GitHub. Retry in a moment.',unknown:'GitHub sign-in failed for an unexpected reason. Check the Vercel function logs for the reference code.'};
