app.get('/api/github/repos',async(req,res)=>{
 const s=await requireUser(req,res);if(!s)return;
 if(!s.githubToken)return res.status(403).json({error:'Connect GitHub as a Developer to discover repositories.',code:'GITHUB_ACCOUNT_REQUIRED',reconnect:true});
 try{
  const githubJson=async(path)=>{
   // Keep each upstream call below the Vercel function's execution budget.
   // Identity and the first repository page are independent GitHub reads, so
   // fetch them together instead of spending two sequential timeout windows.
   const response=await fetch(`${GH}${path}`,{signal:AbortSignal.timeout(12000),headers:{Authorization:`Bearer ${s.githubToken}`,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'}});
   const data=await response.json().catch(()=>({}));
   if(!response.ok){const sso=response.headers.get('x-github-sso')||'';const rateLimited=response.status===403&&(/rate limit/i.test(String(data.message||''))||Number(response.headers.get('x-ratelimit-remaining'))===0);const message=response.status===401?'Your GitHub connection has expired. Reconnect GitHub.':response.status===403?(sso?'GitHub requires organization SSO authorization. Authorize Pothub in your GitHub organization settings.':rateLimited?'GitHub API rate limit reached. Wait briefly, then refresh repositories.':data.message||'GitHub denied repository access. Reconnect and approve repository permissions.'):(data.message||`GitHub API returned ${response.status}`);throw Object.assign(new Error(message),{status:response.status,code:`GITHUB_${response.status}`,reconnect:response.status===401||(response.status===403&&!rateLimited)})}
   return {data,headers:response.headers};
  };
  const firstPagePath='/user/repos?visibility=all&affiliation=owner,collaborator,organization_member&sort=updated&direction=desc&per_page=100&page=1';
  const {identity,firstPage}=await fetchGithubRepositoryBootstrap(githubJson,firstPagePath);
  const scopes=String(identity.headers.get('x-oauth-scopes')||'').split(',').map(v=>v.trim()).filter(Boolean);
  const access=validateGithubRepoAccess({scopes,githubUserId:identity.data?.id,sessionUserId:s.user.id});
  if(!access.ok)throw Object.assign(new Error(access.message),{status:access.status,code:access.code,reconnect:access.reconnect});
  const result=await discoverGithubRepositories(async page=>{
   const response=await githubJson(`/user/repos?visibility=all&affiliation=owner,collaborator,organization_member&sort=updated&direction=desc&per_page=100&page=${page}`);
   return response.data;
  },10,firstPage.data);
  res.setHeader('Cache-Control','no-store, private, max-age=0');
  res.setHeader('Pragma','no-cache');
  res.setHeader('Vary','Cookie, Authorization');
  res.json({ok:true,...result,githubLogin:identity.data.login,scopes,repositoryScope:true,sourceOfTruth:'github'});
 }catch(e){err(res,e,e.status||502)}
});
