app.post('/api/github/agent/commit-approved', async (req, res) => {
  const s = await requireUser(req, res);
  if (!s) return;
  let reviewBranch = '';
  let lastCommitSha = '';
  let committedFiles = [];
  try {
    if (!s.githubToken) throw Object.assign(new Error('Sign in with GitHub to commit an approved change set.'), { status: 403 });
    const fileSchema = z.object({
      path: z.string().min(1).max(240),
      content: z.string().max(340000),
      encoding: z.enum(['utf-8', 'base64']).optional(),
    }).strict();
    const i = z.object({
      approved: z.literal(true),
      owner: z.string().regex(/^[A-Za-z0-9_.-]{1,100}$/),
      repo: z.string().regex(/^[A-Za-z0-9_.-]{1,100}$/),
      baseBranch: z.string().regex(/^[A-Za-z0-9_.-]{1,100}(?:\/[A-Za-z0-9_.-]{1,100})*$/),
      expectedBaseSha: z.string().regex(/^[a-f0-9]{40}$/i),
      scopeClaim: z.string().min(20).max(3000),
      commitMessage: z.string().min(4).max(160),
      files: z.array(fileSchema).min(1).max(80),
    }).parse(req.body);

    let totalBytes = 0;
    const seen = new Set();
    const normalizedFiles = i.files.map((file) => {
      const path = String(file.path).replace(/\\/g, '/');
      if (path.startsWith('/') || path.split('/').some(part => !part || part === '.' || part === '..') || isExcludedRepoPath(path)) {
        throw Object.assign(new Error(`Blocked unsafe or potentially generated/secret-bearing path: ${path}`), { status: 422 });
      }
      if (seen.has(path)) throw Object.assign(new Error(`Duplicate path in approved change set: ${path}`), { status: 422 });
      seen.add(path);
      const encoding = file.encoding || 'utf-8';
      if (encoding === 'base64' && (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(file.content) || file.content.length % 4 !== 0)) {
        throw Object.assign(new Error(`The binary payload for ${path} is not valid base64.`), { status: 422 });
      }
      const bytes = encoding === 'base64' ? Buffer.from(file.content, 'base64') : Buffer.from(file.content, 'utf8');
      totalBytes += bytes.length;
      if (bytes.length > 100 * 1024 * 1024) throw Object.assign(new Error(`File ${path} exceeds GitHub's 100 MB limit. Use Git LFS for large binary assets.`), { status: 413 });
      if (bytes.length > 50 * 1024 * 1024) throw Object.assign(new Error(`File ${path} exceeds the 50 MB review limit. Use Git LFS or split the asset before committing.`), { status: 413 });
      if (encoding === 'utf-8') {
        if (/\.json$/i.test(path)) { try { JSON.parse(file.content); } catch { throw Object.assign(new Error(`The proposed JSON file ${path} is invalid.`), { status: 422 }); } }
        if (/\.(?:[cm]?js|jsx|ts|tsx)$/i.test(path)) assertValidSourceSyntax(path, file.content);
        if (/(^|\/)(?:\.env(?:\..*)?|id_rsa|id_ed25519|credentials\.json|service-account\.json)$/i.test(path) || /(?:^|[._-])(?:secret|private[._-]?key|credentials?)(?:$|[._-])/i.test(path.split('/').pop())) {
          throw Object.assign(new Error(`The path ${path} looks like it may contain credentials. Remove secrets before committing.`), { status: 422 });
        }
      }
      return { path, content: file.content, encoding };
    });
    if (totalBytes > 2500000) throw Object.assign(new Error('This change set exceeds the 2.5 MB safe request limit. Split it into smaller approved batches; use signed uploads for larger assets.'), { status: 413 });

    const touchesWorkflow = normalizedFiles.some(file => file.path.startsWith('.github/workflows/'));
    if (touchesWorkflow) {
      const scopeResponse = await fetch(`${GH}/user`, { headers: { Authorization: `Bearer ${s.githubToken}`, Accept: 'application/vnd.github+json' }, signal: AbortSignal.timeout(10000) });
      const granted = String(scopeResponse.headers.get('x-oauth-scopes') || '').split(',').map(value => value.trim());
      if (!scopeResponse.ok || !granted.includes('workflow')) throw Object.assign(new Error('This change edits GitHub Actions workflows. Reconnect GitHub with the optional workflow permission, then approve again.'), { status: 403, code: 'GITHUB_WORKFLOW_SCOPE_REQUIRED' });
    }

    const prefix = `/repos/${encodeURIComponent(i.owner)}/${encodeURIComponent(i.repo)}`;
    await validatePersistedCodelabScope(s.user.id,i.scopeClaim,{owner:i.owner,repo:i.repo,branch:i.baseBranch});
    const branchPath = i.baseBranch.split('/').map(encodeURIComponent).join('/');
    const baseRef = await gh(s, `${prefix}/git/ref/heads/${branchPath}`);
    if (String(baseRef.object?.sha || '').toLowerCase() !== i.expectedBaseSha.toLowerCase()) throw Object.assign(new Error('The base branch changed after review. Refresh the repository and review the diff again; nothing was committed.'), { status: 409 });
    const parentCommit = await gh(s, `${prefix}/git/commits/${i.expectedBaseSha}`);
    reviewBranch = `pothub/agent-${Date.now().toString(36)}-${crypto.randomBytes(3).toString('hex')}`;
    let parentSha = i.expectedBaseSha;
    let parentTreeSha = parentCommit.tree.sha;
    const batches = [];
    for (let offset = 0; offset < normalizedFiles.length; offset += 12) batches.push(normalizedFiles.slice(offset, offset + 12));

    for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
      const batch = batches[batchIndex];
      const blobs = await Promise.all(batch.map(async file => {
        const payload = file.encoding === 'base64'
          ? { content: file.content, encoding: 'base64' }
          : { content: file.content, encoding: 'utf-8' };
        const blob = await gh(s, `${prefix}/git/blobs`, { method: 'POST', body: JSON.stringify(payload) });
        return { path: file.path, mode: '100644', type: 'blob', sha: blob.sha };
      }));
      const tree = await gh(s, `${prefix}/git/trees`, { method: 'POST', body: JSON.stringify({ base_tree: parentTreeSha, tree: blobs }) });
      const suffix = batches.length > 1 ? ` (${batchIndex + 1}/${batches.length})` : '';
      const commit = await gh(s, `${prefix}/git/commits`, { method: 'POST', body: JSON.stringify({ message: `${i.commitMessage}${suffix}`, tree: tree.sha, parents: [parentSha] }) });
      if (batchIndex === 0) {
        await gh(s, `${prefix}/git/refs`, { method: 'POST', body: JSON.stringify({ ref: `refs/heads/${reviewBranch}`, sha: commit.sha }) });
      } else {
        await gh(s, `${prefix}/git/refs/heads/${reviewBranch.split('/').map(encodeURIComponent).join('/')}`, { method: 'PATCH', body: JSON.stringify({ sha: commit.sha, force: false }) });
      }
      parentSha = commit.sha;
      parentTreeSha = tree.sha;
      lastCommitSha = commit.sha;
      committedFiles.push(...batch.map(file => file.path));
    }

    res.status(201).json({
      ok: true, approved: true, branch: reviewBranch, commitSha: lastCommitSha,
      commitUrl: `https://github.com/${i.owner}/${i.repo}/commit/${lastCommitSha}`,
      branchUrl: `https://github.com/${i.owner}/${i.repo}/tree/${reviewBranch}`,
      files: committedFiles, commitsCreated: batches.length, totalBytes,
      pullRequestRequired: true,
      message: `Approved files were committed in ${batches.length} bounded commit(s) on a review branch. The default branch was not modified; review the branch and create a PR.`,
    });
  } catch (e) {
    if (res.headersSent) return;
    const details = committedFiles.length ? ` A partial review branch may exist at ${reviewBranch}; ${committedFiles.length} file(s) were committed before the error. Review or delete that branch before retrying.` : '';
    err(res, Object.assign(new Error(`${String(e?.message || 'Commit failed')}${details}`), { status: e?.status || 400, code: e?.code }), e instanceof z.ZodError ? 422 : e.status || 400);
  }
});
