  if(!id||id.length>160)throw Object.assign(new Error('The payment provider did not return a valid charge reference.'),{status:409});
  if(order.provider_charge_id&&String(order.provider_charge_id)!==id)
    throw Object.assign(new Error('The payment charge does not match the saved checkout attempt.'),{status:409});
  const grant=await addCredits(String(order.github_id),Number(order.credits),String(order.reference),`Purchased ${order.pack_id} pack`);
  const updated=await db.from('credit_orders').update({status:'paid',provider_charge_id:id,provider_status:'successful',paid_at:order.paid_at||new Date().toISOString()}).eq('reference',String(order.reference)).eq('github_id',String(order.github_id)).neq('status','paid');
