    const paymentMethodId=String(method.data?.id||'');if(!paymentMethodId)throw Object.assign(new Error('Flutterwave did not accept the card details.'),{status:502});
    const redirectUrl=`${origin(req)}/?payment=1&reference=${encodeURIComponent(order.reference)}`;
    const created=await flwFetch('/charges',token,{method:'POST',headers:{'X-Idempotency-Key':order.reference},body:JSON.stringify(buildChargeBody({order,customerId,paymentMethodId,redirectUrl}))});
    const charge=created.data||{};const chargeId=String(charge.id||'');if(!chargeId)throw Object.assign(new Error('Flutterwave did not return a charge ID.'),{status:502});
    await db.from('credit_orders').update({provider_charge_id:chargeId,provider_status:String(charge.status||'pending'),provider_payload:{customerId,customerEmail:form.email.trim().toLowerCase()}}).eq('reference',order.reference);
    res.setHeader('Cache-Control','no-store');
