    if(next.type==='failed'){await db.from('credit_orders').update({status:'failed',provider_status:next.status}).eq('reference',order.reference).neq('status','paid');return res.status(402).json({ok:false,status:'failed',message:'The card was declined. Try a different card.'})}
    if(next.type==='redirect')return res.json({ok:true,status:'requires_redirect',redirectUrl:next.url,message:'Complete your bank\'s card verification to finish paying.'});
    if(next.type==='unsupported')return res.status(422).json({ok:false,status:'unsupported_step',message:'This card needs an extra verification step PotHub does not support yet. Try another card.'});
