app.post('/api/uploads/:uploadId/complete',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const ref=firestore.collection('user_uploads').doc(workspaceOwnerKey(s.user.id)).collection('items').doc(req.params.uploadId),snap=await ref.get();if(!snap.exists)throw Object.assign(new Error('Upload session not found.'),{status:404});const row=snap.data();if(row.state==='complete')return res.json({ok:true,uploadId:row.uploadId,file:row.file,duplicate:true});const file=await verifyUserUploadedObject({userId:s.user.id,path:row.path,maxBytes:100*1024*1024});if(file.size!==Number(row.sizeExpected))throw Object.assign(new Error('Uploaded file size does not match the declared size. Retry the upload from the beginning.'),{status:422});await ref.update({state:'complete',file,completedAt:Date.now()});res.json({ok:true,uploadId:row.uploadId,file})}catch(e){err(res,e,e.status||400)}});
