app.post('/api/codelab/scopes',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{if(!s.githubToken)throw Object.assign(new Error('Connect GitHub before opening Codelab.'),{status:403});if(!firestore)throw Object.assign(new Error('Scope storage is unavailable.'),{status:503});const i=z.object({owner:z.string().regex(/^[A-Za-z0-9_.-]{1,100}$/),repo:z.string().regex(/^[A-Za-z0-9_.-]{1,100}$/),branch:z.string().regex(/^[A-Za-z0-9_.-]{1,100}(?:\/[A-Za-z0-9_.-]{1,100})*$/),threadId:z.string().min(8).max(120)}).strict().parse(req.body);const prefix=`/repos/${encodeURIComponent(i.owner)}/${encodeURIComponent(i.repo)}`;await gh(s,prefix);const branch=await gh(s,`${prefix}/git/ref/heads/${i.branch.split('/').map(encodeURIComponent).join('/')}`);const threadKey=crypto.createHash('sha256').update(`${s.user.id}:${i.threadId}`).digest('hex'),threadRef=firestore.collection('codelab_threads').doc(threadKey);const threadRow={userIdHash:workspaceOwnerKey(s.user.id),owner:i.owner,repo:i.repo,branch:i.branch,threadId:i.threadId,baseSha:branch.object.sha,active:true,createdAt:Date.now(),expiresAt:new Date(Date.now()+8*60*60*1000)};await firestore.runTransaction(async tx=>{const old=await tx.get(threadRef);if(old.exists){const prior=old.data();if(!prior.active||prior.userIdHash!==workspaceOwnerKey(s.user.id)||prior.owner!==i.owner||prior.repo!==i.repo||prior.branch!==i.branch)throw Object.assign(new Error('This Codelab thread is permanently pinned to its original repository and branch. Start a new conversation to change scope.'),{status:409});}else tx.create(threadRef,threadRow)});const token=issueScopeClaim({userId:s.user.id,...i}),hash=crypto.createHash('sha256').update(token).digest('hex');await firestore.collection('codelab_scopes').doc(hash).create({...threadRow,threadKey});res.status(201).json({ok:true,scopeClaim:token,baseSha:branch.object.sha,expiresInSeconds:28800,immutable:true})}catch(e){err(res,e,e instanceof z.ZodError?422:e.status||400)}});
app.post('/api/codelab/scopes/delete',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const i=z.object({scopeClaim:z.string().min(20).max(3000)}).strict().parse(req.body),scope=verifyScopeClaim(i.scopeClaim,{userId:s.user.id}),hash=crypto.createHash('sha256').update(i.scopeClaim).digest('hex'),threadKey=crypto.createHash('sha256').update(`${s.user.id}:${scope.threadId}`).digest('hex'),scopeRef=firestore.collection('codelab_scopes').doc(hash),threadRef=firestore.collection('codelab_threads').doc(threadKey);await firestore.runTransaction(async tx=>{const [a,b]=await Promise.all([tx.get(scopeRef),tx.get(threadRef)]);if(!a.exists||!b.exists||a.data().userIdHash!==workspaceOwnerKey(s.user.id)||b.data().userIdHash!==workspaceOwnerKey(s.user.id))throw Object.assign(new Error('Codelab thread not found.'),{status:404});tx.update(scopeRef,{active:false,deletedAt:Date.now()});tx.update(threadRef,{active:false,deletedAt:Date.now()})});res.json({ok:true,deleted:true})}catch(e){err(res,e,e instanceof z.ZodError?422:403)}});
app.post('/api/codelab/scopes/verify',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const i=z.object({scopeClaim:z.string().min(20).max(3000),target:z.object({owner:z.string(),repo:z.string(),branch:z.string()}).strict()}).strict().parse(req.body),scope=verifyScopeClaim(i.scopeClaim,{userId:s.user.id}),hash=crypto.createHash('sha256').update(i.scopeClaim).digest('hex'),snap=await firestore.collection('codelab_scopes').doc(hash).get();if(!snap.exists||!snap.data().active||snap.data().userIdHash!==workspaceOwnerKey(s.user.id))throw Object.assign(new Error('Codelab scope was revoked or belongs to another account.'),{status:403});assertScopeTarget(scope,i.target);res.json({ok:true,scope:{owner:scope.owner,repo:scope.repo,branch:scope.branch,threadId:scope.threadId,expiresAt:scope.exp}})}catch(e){err(res,e,e instanceof z.ZodError?422:403)}});
app.use('/api',(req,res)=>res.status(404).json({error:`API route not found: ${req.method} ${req.path}`,code:'POTHUB_ROUTE_NOT_FOUND',requestId:req.requestId}));app.use((e,req,res,next)=>{const requestId=req.requestId||crypto.randomUUID();const status=Number(e?.status||e?.statusCode)||(e?.type==='entity.too.large'?413:500);const safe=redactSecrets(String(e?.message||'Unexpected server error.')).slice(0,400);console.error('[Pothub unhandled]',JSON.stringify({requestId,status,message:safe}));if(res.headersSent)return next(e);res.status(status).json({error:status>=500?'Unexpected server error. Check the diagnostic ID and server logs.':safe,code:e?.type==='entity.too.large'?'POTHUB_BODY_TOO_LARGE':`HTTP_${status}`,requestId})});export default app;

